from __future__ import annotations

from pathlib import Path

ROOT = Path(__file__).resolve().parents[2]
TYPES = ROOT / "src/mqttium/types.py"
CLIENT = ROOT / "src/mqttium/api/async_client.py"
MEMORY_TEST = ROOT / "tests/unit/test_memory_cleanup.py"
RESERVATION_TEST = ROOT / "tests/unit/test_external_delivery_accounting.py"


def replace_once(text: str, old: str, new: str, *, label: str) -> str:
    count = text.count(old)
    if count != 1:
        raise RuntimeError(f"{label}: expected one match, found {count}")
    return text.replace(old, new, 1)


def patch_types() -> None:
    text = TYPES.read_text()
    old = '''    # Internal delivery accounting. Public Message instances remain frozen;\n    # AsyncClient mutates only these private slots with object.__setattr__.\n    _delivery_logical_bytes: int = field(default=0, init=False, repr=False, compare=False)\n    _delivery_references: int = field(default=0, init=False, repr=False, compare=False)\n'''
    text = replace_once(text, old, "", label="Message private delivery slots")
    TYPES.write_text(text)


def patch_client() -> None:
    text = CLIENT.read_text()

    old_aliases = '''MessageDelivery = Literal["auto", "iterator", "callback", "both"]\nPublishBackpressure = Literal["wait", "error"]\nDeliveryToken = int | Message | None\nCallbackJob = tuple[Callable[..., Any], tuple[Any, ...], DeliveryToken]\nTrackedIteratorMessage = tuple[Message, Message]\nIteratorQueueItem = Message | TrackedIteratorMessage\n\n\nclass _DeliveryQueue(asyncio.Queue[IteratorQueueItem]):\n'''
    new_aliases = '''MessageDelivery = Literal["auto", "iterator", "callback", "both"]\nPublishBackpressure = Literal["wait", "error"]\n\n\nclass _SharedDeliveryReservation:\n    """One exact byte reservation shared by callback and iterator delivery."""\n\n    __slots__ = ("logical_bytes", "remaining")\n\n    def __init__(self, logical_bytes: int) -> None:\n        self.logical_bytes = logical_bytes\n        self.remaining = 2\n\n\nAccountedDeliveryToken = int | _SharedDeliveryReservation\nDeliveryToken = AccountedDeliveryToken | None\nCallbackJob = tuple[Callable[..., Any], tuple[Any, ...], DeliveryToken]\nTrackedIteratorMessage = tuple[Message, AccountedDeliveryToken]\nIteratorQueueItem = Message | TrackedIteratorMessage\n\n\nclass _DeliveryQueue(asyncio.Queue[IteratorQueueItem]):\n'''
    text = replace_once(text, old_aliases, new_aliases, label="delivery type aliases")

    old_reserve_inline = '''            delivery_token: DeliveryToken = None\n            iterator_enqueued = False\n            callback_enqueued = False\n            if references:\n                logical_bytes = self._delivery_logical_size(msg)\n                limit = self._delivery_accounted_limit\n                if limit is not None and logical_bytes > limit:\n                    raise MessageDeliveryError(\n                        f"Message requires {logical_bytes} delivery bytes, exceeding limit {limit}"\n                    )\n                if limit is None or self._pending_delivery_bytes + logical_bytes <= limit:\n                    self._pending_delivery_bytes += logical_bytes\n                    if self._pending_delivery_bytes > self._pending_delivery_high_water_bytes:\n                        self._pending_delivery_high_water_bytes = self._pending_delivery_bytes\n                    if references == 1 and callback_delivery:\n                        delivery_token = logical_bytes\n                    else:\n                        if msg._delivery_logical_bytes or msg._delivery_references:\n                            raise MQTTError("Duplicate delivery reservation for one Message object")\n                        object.__setattr__(msg, "_delivery_logical_bytes", logical_bytes)\n                        if references > 1:\n                            object.__setattr__(msg, "_delivery_references", references)\n                        delivery_token = msg\n                else:\n                    delivery_token = await self._reserve_delivery_slow(\n                        msg,\n                        references,\n                        logical_bytes,\n                        callback_delivery=callback_delivery,\n                    )\n'''
    new_reserve_inline = '''            delivery_token: DeliveryToken = None\n            iterator_enqueued = False\n            callback_enqueued = False\n            if references:\n                logical_bytes = self._delivery_logical_size(msg)\n                limit = self._delivery_accounted_limit\n                if limit is not None and logical_bytes > limit:\n                    raise MessageDeliveryError(\n                        f"Message requires {logical_bytes} delivery bytes, exceeding limit {limit}"\n                    )\n                delivery_token = self._try_reserve_delivery(logical_bytes, references)\n                if delivery_token is None:\n                    delivery_token = await self._reserve_delivery_slow(\n                        logical_bytes, references\n                    )\n'''
    text = replace_once(text, old_reserve_inline, new_reserve_inline, label="inline reservation")

    old_iterator_item = '''                    iterator_item: IteratorQueueItem = (\n                        (msg, delivery_token) if isinstance(delivery_token, Message) else msg\n                    )\n'''
    new_iterator_item = '''                    iterator_item: IteratorQueueItem = (\n                        (msg, delivery_token) if delivery_token is not None else msg\n                    )\n'''
    text = replace_once(text, old_iterator_item, new_iterator_item, label="iterator token")

    old_methods = '''    def _try_reserve_delivery(\n        self,\n        message: Message,\n        references: int,\n        logical_bytes: int,\n        *,\n        callback_delivery: bool,\n    ) -> DeliveryToken:\n        limit = self._delivery_accounted_limit\n        if limit is not None and self._pending_delivery_bytes + logical_bytes > limit:\n            return None\n        if message._delivery_logical_bytes or message._delivery_references:\n            raise MQTTError("Duplicate delivery reservation for one Message object")\n        self._pending_delivery_bytes += logical_bytes\n        if self._pending_delivery_bytes > self._pending_delivery_high_water_bytes:\n            self._pending_delivery_high_water_bytes = self._pending_delivery_bytes\n        if references == 1 and callback_delivery:\n            # The callback job already needs a token slot, so carrying the byte\n            # count there avoids mutating or indexing the Message object.\n            return logical_bytes\n        object.__setattr__(message, "_delivery_logical_bytes", logical_bytes)\n        if references > 1:\n            object.__setattr__(message, "_delivery_references", references)\n        return message\n\n    async def _reserve_delivery(self, message: Message, references: int) -> DeliveryToken:\n        logical_bytes = self._delivery_logical_size(message)\n        limit = self._delivery_accounted_limit\n        if limit is not None and logical_bytes > limit:\n            raise MessageDeliveryError(\n                f"Message requires {logical_bytes} delivery bytes, exceeding limit {limit}"\n            )\n        callback_delivery = references == 1 and self.on_message is not None\n        token = self._try_reserve_delivery(\n            message, references, logical_bytes, callback_delivery=callback_delivery\n        )\n        if token is not None:\n            return token\n        return await self._reserve_delivery_slow(\n            message,\n            references,\n            logical_bytes,\n            callback_delivery=callback_delivery,\n        )\n\n    async def _reserve_delivery_slow(\n        self,\n        message: Message,\n        references: int,\n        logical_bytes: int,\n        *,\n        callback_delivery: bool,\n    ) -> DeliveryToken:\n        while True:\n            self._delivery_waiters += 1\n            try:\n                self._delivery_space.clear()\n                token = self._try_reserve_delivery(\n                    message,\n                    references,\n                    logical_bytes,\n                    callback_delivery=callback_delivery,\n                )\n                if token is not None:\n                    return token\n                await self._delivery_space.wait()\n            finally:\n                self._delivery_waiters -= 1\n            token = self._try_reserve_delivery(\n                message,\n                references,\n                logical_bytes,\n                callback_delivery=callback_delivery,\n            )\n            if token is not None:\n                return token\n\n    def _release_delivery_reference_nowait(self, token: int | Message) -> None:\n        if isinstance(token, int):\n            self._pending_delivery_bytes -= token\n        else:\n            references = token._delivery_references\n            if references > 1:\n                object.__setattr__(token, "_delivery_references", references - 1)\n                return\n            if references == 1:\n                object.__setattr__(token, "_delivery_references", 0)\n            logical_bytes = token._delivery_logical_bytes\n            if logical_bytes <= 0:\n                return\n            object.__setattr__(token, "_delivery_logical_bytes", 0)\n            self._pending_delivery_bytes -= logical_bytes\n        if self._delivery_waiters:\n            self._delivery_space.set()\n\n    async def _release_delivery_reference(self, token: int | Message) -> None:\n        self._release_delivery_reference_nowait(token)\n'''
    new_methods = '''    def _try_reserve_delivery(\n        self, logical_bytes: int, references: int\n    ) -> DeliveryToken:\n        limit = self._delivery_accounted_limit\n        if limit is not None and self._pending_delivery_bytes + logical_bytes > limit:\n            return None\n        self._pending_delivery_bytes += logical_bytes\n        if self._pending_delivery_bytes > self._pending_delivery_high_water_bytes:\n            self._pending_delivery_high_water_bytes = self._pending_delivery_bytes\n        if references == 1:\n            return logical_bytes\n        # `references` is derived from callback_delivery + iterator_delivery,\n        # so the only remaining runtime case is exactly two consumers.\n        return _SharedDeliveryReservation(logical_bytes)\n\n    async def _reserve_delivery(self, message: Message, references: int) -> DeliveryToken:\n        logical_bytes = self._delivery_logical_size(message)\n        limit = self._delivery_accounted_limit\n        if limit is not None and logical_bytes > limit:\n            raise MessageDeliveryError(\n                f"Message requires {logical_bytes} delivery bytes, exceeding limit {limit}"\n            )\n        token = self._try_reserve_delivery(logical_bytes, references)\n        if token is not None:\n            return token\n        return await self._reserve_delivery_slow(logical_bytes, references)\n\n    async def _reserve_delivery_slow(\n        self, logical_bytes: int, references: int\n    ) -> DeliveryToken:\n        while True:\n            self._delivery_waiters += 1\n            try:\n                self._delivery_space.clear()\n                token = self._try_reserve_delivery(logical_bytes, references)\n                if token is not None:\n                    return token\n                await self._delivery_space.wait()\n            finally:\n                self._delivery_waiters -= 1\n            token = self._try_reserve_delivery(logical_bytes, references)\n            if token is not None:\n                return token\n\n    def _release_delivery_reference_nowait(self, token: AccountedDeliveryToken) -> None:\n        if isinstance(token, int):\n            self._pending_delivery_bytes -= token\n        else:\n            remaining = token.remaining\n            if remaining <= 0:\n                return\n            remaining -= 1\n            token.remaining = remaining\n            if remaining:\n                return\n            logical_bytes = token.logical_bytes\n            token.logical_bytes = 0\n            self._pending_delivery_bytes -= logical_bytes\n        if self._delivery_waiters:\n            self._delivery_space.set()\n\n    async def _release_delivery_reference(self, token: AccountedDeliveryToken) -> None:\n        self._release_delivery_reference_nowait(token)\n'''
    text = replace_once(text, old_methods, new_methods, label="reservation helpers")

    old_worker_release = '''                    if delivery_token is not None:\n                        if isinstance(delivery_token, int):\n                            self._pending_delivery_bytes -= delivery_token\n                            if self._delivery_waiters:\n                                self._delivery_space.set()\n                        else:\n                            self._release_delivery_reference_nowait(delivery_token)\n'''
    new_worker_release = '''                    if delivery_token is not None:\n                        self._release_delivery_reference_nowait(delivery_token)\n'''
    text = replace_once(text, old_worker_release, new_worker_release, label="callback release")

    if "_delivery_logical_bytes" in text or "_delivery_references" in text:
        raise RuntimeError("Message-embedded delivery accounting remains in async_client.py")
    CLIENT.write_text(text)


def patch_memory_test() -> None:
    text = MEMORY_TEST.read_text()
    old = '''    assert client._messages.empty()\n    assert client.pending_delivery_bytes == 0\n    assert message._delivery_references == 0\n    assert message._delivery_logical_bytes == 0\n'''
    new = '''    assert client._messages.empty()\n    assert client.pending_delivery_bytes == 0\n    assert not hasattr(message, "_delivery_references")\n    assert not hasattr(message, "_delivery_logical_bytes")\n'''
    text = replace_once(text, old, new, label="memory cleanup assertions")
    MEMORY_TEST.write_text(text)


def write_reservation_tests() -> None:
    RESERVATION_TEST.write_text(
        '''from mqttium.api import AsyncClient\nfrom mqttium.types import Message\n\n\ndef test_message_has_only_public_delivery_data() -> None:\n    message = Message(topic="test/topic", payload=b"payload")\n\n    assert not hasattr(message, "_delivery_logical_bytes")\n    assert not hasattr(message, "_delivery_references")\n\n\ndef test_single_consumer_uses_compact_integer_token() -> None:\n    client = AsyncClient(max_pending_delivery_bytes=1_024, message_delivery="iterator")\n\n    token = client._try_reserve_delivery(100, 1)\n\n    assert token == 100\n    assert client.pending_delivery_bytes == 100\n    client._release_delivery_reference_nowait(token)\n    assert client.pending_delivery_bytes == 0\n\n\ndef test_shared_reservation_releases_on_last_consumer() -> None:\n    client = AsyncClient(max_pending_delivery_bytes=1_024, message_delivery="both")\n\n    token = client._try_reserve_delivery(100, 2)\n\n    assert token is not None\n    assert not isinstance(token, int)\n    assert client.pending_delivery_bytes == 100\n\n    client._release_delivery_reference_nowait(token)\n    assert client.pending_delivery_bytes == 100\n    client._release_delivery_reference_nowait(token)\n    assert client.pending_delivery_bytes == 0\n\n\ndef test_shared_reservation_ignores_duplicate_release() -> None:\n    client = AsyncClient(max_pending_delivery_bytes=1_024, message_delivery="both")\n    token = client._try_reserve_delivery(100, 2)\n    assert token is not None\n\n    client._release_delivery_reference_nowait(token)\n    client._release_delivery_reference_nowait(token)\n    client._release_delivery_reference_nowait(token)\n\n    assert client.pending_delivery_bytes == 0\n\n\ndef test_same_message_can_have_independent_reservations() -> None:\n    client = AsyncClient(max_pending_delivery_bytes=1_024, message_delivery="iterator")\n    message = Message(topic="test/topic", payload=b"payload")\n\n    first = client._try_reserve_delivery(client._delivery_logical_size(message), 1)\n    second = client._try_reserve_delivery(client._delivery_logical_size(message), 1)\n\n    assert first is not None\n    assert second is not None\n    assert client.pending_delivery_bytes == first + second\n    client._release_delivery_reference_nowait(first)\n    client._release_delivery_reference_nowait(second)\n    assert client.pending_delivery_bytes == 0\n'''
    )


def main() -> None:
    patch_types()
    patch_client()
    patch_memory_test()
    write_reservation_tests()


if __name__ == "__main__":
    main()
